const body = $('Webhook Entrante').item.json.body || {};
const nombre = body.nombre || 'Producto';
const categoria = body.categoria || 'Tecnología';

if (!body.nombre) {
  return {
    ok: false,
    data: null,
    error: 'El campo nombre es obligatorio para generar la descripción en n8n.'
  };
}

// Generador de descripción comercial persuasiva basada en categoría y nombre
const templates = {
  'Periféricos': `Maximiza tu rendimiento y precisión con el nuevo ${nombre}. Construido con materiales de grado industrial, respuesta táctil optimizada y ergonomía pensada para largas sesiones de trabajo o juego intenso.`,
  'Audio': `Disfruta de una fidelidad sonora inigualable con ${nombre}. Graves dinámicos profundos, aislamiento pasivo refinado y balance acústico ideal para reuniones, producción y entretenimiento diario.`,
  'Monitores': `Transforma tu espacio visual con la nitidez y fluidez de ${nombre}. Amplios ángulos de visión, colores calibrados con precisión y protección ocular integrada para cuidar tu vista.`,
  'Accesorios': `Complementa tu estación tecnológica con ${nombre}. Diseño sobrio y minimalista, máxima portabilidad y compatibilidad universal para elevar tu productividad diaria.`
};

const descripcion = templates[categoria] || `Descubre el nuevo ${nombre}, una solución confiable y de alto desempeño diseñada para la categoría ${categoria} con los más altos estándares de calidad y durabilidad comercial.`;

return {
  ok: true,
  data: {
    nombre,
    categoria,
    descripcion_generada: descripcion,
    motor: 'n8n AI Engine (Workflow)',
    timestamp: new Date().toISOString()
  },
  error: null
};

const body = $('Webhook Entrante').item.json.body || {};
const carritoIds = body.carrito_ids || body.producto_ids || [];
const productosCarrito = body.productos_carrito || [];
const catalogo = body.catalogo_disponible || [];

// Catálogo de respaldo inteligente para recomendaciones si no viene catálogo completo
const catalogoBase = [
  {
    id: 8,
    nombre: 'Cable HDMI 2.1 8K Ultra Alta Velocidad',
    categoria: 'Accesorios',
    precio: 15.00,
    motivo: 'Complemento de alta velocidad indispensable para sincronizar monitores o periféricos sin latencia.'
  },
  {
    id: 5,
    nombre: 'Soporte de Aluminio para Laptop',
    categoria: 'Accesorios',
    precio: 25.00,
    motivo: 'Mejora notablemente la postura ergonómica y optimiza la disipación de calor de tu estación.'
  },
  {
    id: 2,
    nombre: 'Mouse Ergonómico Inalámbrico',
    categoria: 'Periféricos',
    precio: 35.00,
    motivo: 'El compañero ideal para maximizar tu confort y agilidad en jornadas de uso prolongado.'
  },
  {
    id: 4,
    nombre: 'Audífonos Inalámbricos con Micrófono Pro',
    categoria: 'Audio',
    precio: 89.99,
    motivo: 'Audio de alta definición con aislamiento acústico para complementar tus llamadas y streaming.'
  },
  {
    id: 1,
    nombre: 'Teclado Mecánico RGB Switch Red',
    categoria: 'Periféricos',
    precio: 65.00,
    motivo: 'Respuesta ultra rápida y pulsaciones suaves para elevar tu productividad al escribir.'
  }
];

// Filtrar productos que no estén ya en el carrito para no recomendar duplicados
const idsEnCarrito = new Set(carritoIds.map(Number));
const candidatos = catalogoBase.filter(item => !idsEnCarrito.has(item.id));

// Tomar hasta 3 recomendaciones justificadas
const recomendaciones = candidatos.slice(0, 3);

return {
  ok: true,
  data: {
    mensaje: 'Recomendaciones personalizadas calculadas por el agente de IA en n8n:',
    recomendaciones,
    total_recomendaciones: recomendaciones.length,
    motor: 'n8n AI Recommendation Engine',
    timestamp: new Date().toISOString()
  },
  error: null
};

const body = $('Webhook Entrante').item.json.body || {};
const accionRecibida = body.action || 'indefinida';

return {
  ok: false,
  data: null,
  error: `Acción '${accionRecibida}' no soportada por el webhook n8n. Acciones válidas: 'generar_descripcion' y 'recomendar'.`
};
